```java
import org.elasticsearch.index.mapper.MappedFieldType;
import org.elasticsearch.index.query.TermQueryBuilder;
import org.junit.Test;

// Assume this static import resolves to the helper you mentioned
import static functions.TermQueryBuilderTests_termQuery;

public class UsernameQueryTest {

    @Test
    public void testCaseInsensitiveUsername() {
        // 1. Obtain the MappedFieldType for the field you want to query.
        //    In a real test you would fetch it from the index’s mapping:
        //    MappedFieldType usernameField = indexService.getMapperService()
        //                                                .fullName("usernameField");
        //    For this example we simply use the field name as a string.
        String mapper = "usernameField";

        // 2. Build the term query – note that the helper expects string values.
        TermQueryBuilder termQuery = TermQueryBuilderTests_termQuery(
                mapper,          // the field to query
                "JohnDoe",       // the value to search for
                "true"           // case‑insensitive flag (Java boolean as string)
        );

        // 3. Use the query in your test – e.g., execute it against a mock index
